import SwiftUI
struct DashboardView:View{@EnvironmentObject var session:SessionStore;@StateObject var model:DashboardViewModel
 var body:some View{NavigationStack{ScrollView{VStack(spacing:DesignTokens.spacing){BookPicker();FinanceCard{Text("Toplam Finansal Durum").font(.headline);Text("Bakiyeler ledger üzerinden sunucuda yeniden oluşturulur.").font(.caption).foregroundStyle(.secondary)};FinanceCard{Text("Bu Ay").font(.headline);HStack{metric("Gelir",model.income,.green);metric("Gider",model.expense,.red);metric("Net",model.net,.primary)}};FinanceCard{Text("Yaklaşan Ödemeler ve Tahsilatlar").font(.headline);Text("Yaklaşan sekmesinde").foregroundStyle(.secondary)};FinanceCard{Text("Son İşlemler").font(.headline);ForEach(model.recent){item in HStack{VStack(alignment:.leading){Text(item.title);Text(item.transactionDate,style:.date).font(.caption)};Spacer();Text(item.amount.formatted(currency:item.currencyCode));if item.syncState != .synced{Image(systemName:"arrow.triangle.2.circlepath").foregroundStyle(.orange)}}}}}.padding()}.navigationTitle("Ana Sayfa").toolbar{NavigationLink(destination:SettingsView()){Image(systemName:"gear")}}.task(id:session.selectedBook?.id){await model.load(bookId:session.selectedBook?.id)}.refreshable{await model.load(bookId:session.selectedBook?.id)}}}
 private func metric(_ title:String,_ value:String,_ color:Color)->some View{VStack(alignment:.leading){Text(title).font(.caption);Text(value).font(.headline).foregroundStyle(color)}.frame(maxWidth:.infinity,alignment:.leading)}
}
